"""Verify radiographic pinhole projection identities with authored inputs."""

import json
from pathlib import Path

from matintegrity.models.radiography import (
    RadiographicExamination,
    radiographic_geometry_summary,
)

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "validation/radiography_math.json"
EVIDENCE = {
    "source_id": "authored-radiography-validation",
    "origin": "synthetic",
    "citation": "independent synthetic verification generated by this project",
}


def main():
    examination = RadiographicExamination.model_validate(
        {
            "examination_id": "authored-rt",
            "procedure_id": "authored-procedure",
            "procedure_revision": "1",
            "physical_scope_id": "authored-weld",
            "material_condition_id": "authored-material",
            "source_kind": "x_ray",
            "source_equipment_id": "authored-source",
            "tube_voltage_V": 200000.0,
            "focal_spot_size_m": 0.001,
            "exposure_time_s": 20.0,
            "source_object_distance_m": 1.0,
            "object_detector_distance_m": 0.2,
            "nominal_object_thickness_m": 0.02,
            "detector_kind": "digital_detector_array",
            "detector_id": "authored-detector",
            "detector_calibration_basis": "authored calibration record",
            "image_id": "authored-image",
            "image_sha256": "a" * 64,
            "image_width_px": 2000,
            "image_height_px": 1000,
            "detector_pixel_pitch_m": 0.0002,
            "image_quality_records": [
                {
                    "iqi_id": "authored-iqi",
                    "iqi_type": "authored indicator",
                    "placement": "source_side",
                    "placement_basis": "authored placement record",
                    "reported_image_quality_result": "authored result",
                    "result_basis": "authored review",
                    "reviewed": True,
                    "evidence": [EVIDENCE],
                }
            ],
            "indications": [],
            "source_configuration_reviewed": True,
            "projection_geometry_reviewed": True,
            "exposure_reviewed": True,
            "detector_calibration_reviewed": True,
            "image_identity_reviewed": True,
            "image_quality_reviewed": True,
            "indication_mapping_reviewed": True,
            "negative_result_reviewed": True,
            "evidence": [EVIDENCE],
        }
    )
    result = radiographic_geometry_summary(examination)
    expected = {
        "source_detector_distance_m": 1.2,
        "magnification": 1.2,
        "geometric_unsharpness_m": 0.0002,
        "object_plane_pixel_pitch_m": 0.0002 / 1.2,
    }
    for key, value in expected.items():
        if abs(result.values[key] - value) > 1e-15:
            raise ValueError(f"radiographic projection identity failed for {key}")
    if result.status != "computed":
        raise ValueError("fully reviewed authored radiographic record did not compute")
    report = {
        "schema": "matintegrity.radiography_math.v1",
        "expected": expected,
        "computed": {key: result.values[key] for key in expected},
        "qualification": (
            "Synthetic pinhole-geometry and contract verification only; no source, detector, IQI, "
            "procedure, indication detection, sizing or acceptance is qualified."
        ),
    }
    OUTPUT.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
